// Print a 3x3 grid
for (int row = 1; row <= 3; row++)
{
    for (int col = 1; col <= 3; col++)
    {
        Console.Write("* ");
    }
    Console.WriteLine();
}

// Multiplication table
for (int i = 1; i <= 3; i++)
{
    for (int j = 1; j <= 3; j++)
    {
        Console.Write((i * j) + " ");
    }
    Console.WriteLine();
}

// Pyramid pattern
for (int row = 1; row <= 5; row++)
{
    for (int space = 1; space <= 5 - row; space++)
    {
        Console.Write(" ");
    }
    for (int star = 1; star <= row; star++)
    {
        Console.Write("*");
    }
    Console.WriteLine();
}
